def durable_commit_evolution_bundle(self,bundle:Mapping[str,Mapping[str,Any]],gate:Mapping[str,Any])->Dict[str,Any]:
        if not self.canonical_state.get('canonical_durable_mutation'):return {'committed':False,'reason':'DURABLE_MUTATION_DISABLED'}
        if not gate.get('passed'):return {'committed':False,'reason':'VALIDATION_GATE_FAILED'}
        allowed={'LOGIC','THINKING','INTELLIGENCE'}
        if set(bundle)!=allowed:return {'committed':False,'reason':'BUNDLE_MUST_COVER_THREE_ORGANS'}
        before=self.state_path.read_bytes();before_sha=hashlib.sha256(before).hexdigest();st=json.loads(before)
        registry={}
        for organ,c in bundle.items():
            registry[organ]={'model_type':{'LOGIC':'BOOLEAN_PROGRAM','THINKING':'PRECEDENCE_GRAPH','INTELLIGENCE':'STRATEGY_TREE'}[organ], 'model':c['model'],'evidence':{'blind':c['blind'],'ablation':c['ablation'],'restore':c['restore']}}
        st['organ_autoevolution_registry']=registry;st['organ_autoevolution_enabled']=True
        self._atomic_write_json(self.state_path,st);self.reload_canonical_state();after_sha=hashlib.sha256(self.state_path.read_bytes()).hexdigest()
        return {'committed':True,'before_sha256':before_sha,'after_sha256':after_sha}

def register_point(self, token: str, permissions: Optional[Sequence[str]] = None) -> Dict[str, Any]:
        token_hash = hashlib.sha256(token.encode("utf-8")).hexdigest()
        with self.db_lock:
            row = self.conn.execute("SELECT expires_at FROM registration_tokens WHERE token_hash=?", (token_hash,)).fetchone()
            if row is None:
                return {"status": "error", "message": "invalid token"}
            if time.time() > float(row["expires_at"]):
                self.conn.execute("DELETE FROM registration_tokens WHERE token_hash=?", (token_hash,))
                self.conn.commit()
                return {"status": "error", "message": "token expired"}
            key_id = secrets.token_urlsafe(16)
            secret = secrets.token_urlsafe(32)
            encrypted = self._cipher.encrypt(secret.encode("utf-8"))
            perms = list(permissions or ["read"])
            self.conn.execute(
                "INSERT INTO access_keys(key_id, encrypted_secret, permissions, created_at) VALUES(?,?,?,?)",
                (key_id, encrypted, canonical_json(perms), utc_now().isoformat()),
            )
            self.conn.execute("DELETE FROM registration_tokens WHERE token_hash=?", (token_hash,))
            self.conn.commit()
        return {"status": "success", "key_id": key_id, "key_secret": secret, "permissions": perms}

def durable_commit_evolution_bundle(self,bundle:Mapping[str,Mapping[str,Any]],gate:Mapping[str,Any])->dict[str,Any]:
        try: current=self.state_path.resolve(); target=DEFAULT_STATE.resolve()
        except Exception: current=self.state_path; target=DEFAULT_STATE
        if current!=target:
            return {'committed':False,'reason':'HISTORICAL_OR_NONACTIVE_STATE_IMMUTABLE_IN_R7','state_path':str(current),'active_state_path':str(target)}
        return super().durable_commit_evolution_bundle(bundle,gate)

def evaluate_evolution_skill(self, candidate, **gate_kwargs):
        c = candidate if isinstance(candidate, SkillCandidate) else SkillCandidate(**candidate)
        return SkillAdmissionGate(**gate_kwargs).evaluate(c)

def select_evolution_skills(self, candidates, max_skills:int=8, **gate_kwargs):
        xs=[c if isinstance(c, SkillCandidate) else SkillCandidate(**c) for c in candidates]
        return SkillAdmissionGate(**gate_kwargs).select_subset(xs,max_skills=max_skills)
